def scope_reading(p):
    q = ('NOT', p)
    return {
      'exhaustive_alternative': ('NECESSARY', ('OR', p, q)),
      'positive_disjunct': ('NECESSARY', p),
      'negative_disjunct': ('NECESSARY', q),
      'open_result': ('OPEN_ALTERNATIVE', p, q)
    }

sea = scope_reading('SEA_BATTLE_TOMORROW')
cloak = scope_reading('CLOAK_CUT_IN_HALF')
result = {
  'sea': sea,
  'cloak': cloak,
  'cloak_outcome': ('WEAR_OUT_FIRST', 'CLOAK')
}
